import{_ as t,o,c as i,a2 as r}from"./chunks/framework.mRCPFc5l.js";const s="/assets/subtitle-mapping.DQdtHKp-.png",a="/assets/video-mapping.B1-iokE-.png",n="/assets/project-parameters.Rz626UAc.png",l="/assets/project-setup-import.CELnUq1G.png",b=JSON.parse('{"title":"Importing Resources","description":"","frontmatter":{},"headers":[],"relativePath":"en_US/02-importing-resources.md","filePath":"en_US/02-importing-resources.md"}'),d={name:"en_US/02-importing-resources.md"};function p(c,e,h,m,g,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="importing-resources" tabindex="-1">Importing Resources <a class="header-anchor" href="#importing-resources" aria-label="Permalink to &quot;Importing Resources&quot;">​</a></h1><p>Build a reliable project by importing subtitles and videos, then confirming every episode assignment.</p><h2 id="what-you-can-do-on-this-page" tabindex="-1">What you can do on this page <a class="header-anchor" href="#what-you-can-do-on-this-page" aria-label="Permalink to &quot;What you can do on this page&quot;">​</a></h2><ul><li>Create the project folder and import source/translation subtitles.</li><li>Import videos and map filenames to episodes.</li><li>Correct missing, duplicate, or ambiguous episode assignments.</li><li>Set project-wide quality and translation parameters.</li></ul><h2 id="create-a-project-folder" tabindex="-1">Create a project folder <a class="header-anchor" href="#create-a-project-folder" aria-label="Permalink to &quot;Create a project folder&quot;">​</a></h2><p>Choose <strong>New Project</strong>, then select or create the folder that will own the project. Use a stable writable location. GridSubStudio creates its managed structure inside this folder; avoid manually renaming managed files while the project is open.</p><h2 id="import-original-subtitles" tabindex="-1">Import original subtitles <a class="header-anchor" href="#import-original-subtitles" aria-label="Permalink to &quot;Import original subtitles&quot;">​</a></h2><p>In <strong>Project Setup → Import</strong>, choose <strong>Import Original</strong> and select supported ASS, SSA, or SRT files. The imported text populates the source column. ASS/SSA files also retain template information needed for styled ASS export.</p><h2 id="import-translated-subtitles" tabindex="-1">Import translated subtitles <a class="header-anchor" href="#import-translated-subtitles" aria-label="Permalink to &quot;Import translated subtitles&quot;">​</a></h2><p>Choose <strong>Import Translation</strong> when translation files already exist. Translation imports are aligned with source rows by episode, timing, and content. When imported rows differ from existing rows, GridSubStudio opens a review step instead of silently overwriting work.</p><p>Do not mix <strong>Whole Replacement</strong> and <strong>Precise Update</strong> in one subtitle import batch. Finish or cancel the current batch before changing modes.</p><h2 id="import-videos" tabindex="-1">Import videos <a class="header-anchor" href="#import-videos" aria-label="Permalink to &quot;Import videos&quot;">​</a></h2><p>Choose <strong>Import Videos</strong> and select files or a folder. Videos are referenced as project resources; importing them does not embed the media into <code>workspace.csv</code>.</p><p>Each episode should resolve to one video. Missing videos do not prevent subtitle editing, but video playback and timing review will be unavailable for that episode.</p><h2 id="review-and-correct-episodes" tabindex="-1">Review and correct episodes <a class="header-anchor" href="#review-and-correct-episodes" aria-label="Permalink to &quot;Review and correct episodes&quot;">​</a></h2><p>Open <strong>Subtitle Filename Mapping</strong> after importing subtitles.</p><p><img src="'+s+'" alt="Original subtitle filename mapping with four files and one unresolved episode"></p><ol><li>Review the episode detected from each filename.</li><li>Edit an empty or incorrect episode cell directly.</li><li>Resolve duplicate episode assignments.</li><li>Check files marked <strong>Needs review</strong> or <strong>No episode</strong>.</li></ol><p>Then open <strong>Video Filename Mapping</strong> and perform the same checks.</p><p><img src="'+a+'" alt="Video filename mapping with detected episodes and an unresolved file"></p><p>A low-confidence match is a review warning, not a final blocker by itself. Missing episodes, conflicts, unresolved resources, or import errors must be corrected before confirmation.</p><h2 id="handle-unrecognized-or-duplicate-files" tabindex="-1">Handle unrecognized or duplicate files <a class="header-anchor" href="#handle-unrecognized-or-duplicate-files" aria-label="Permalink to &quot;Handle unrecognized or duplicate files&quot;">​</a></h2><ul><li>Rename ambiguous files before import when practical.</li><li>Enter the episode manually when filename detection is wrong.</li><li>Remove accidental duplicate selections rather than assigning two source files to the same episode.</li><li>When several video candidates are shown, select the correct match explicitly.</li></ul><p>Episode values are normalized: values such as <code>4</code>, <code>04</code>, and <code>004</code> represent the same episode and can conflict.</p><h2 id="set-project-parameters" tabindex="-1">Set project parameters <a class="header-anchor" href="#set-project-parameters" aria-label="Permalink to &quot;Set project parameters&quot;">​</a></h2><p>Open <strong>Other Parameters</strong> to set:</p><ul><li><strong>Maximum CPS</strong> for reading-speed alerts.</li><li><strong>Line length</strong> used by long-line checks and line breaking.</li><li><strong>Target language</strong> for machine translation.</li><li><strong>Spellcheck language</strong>, chosen from installed dictionaries.</li></ul><p><img src="'+n+'" alt="Project parameters for quality thresholds, language, and dictionary"></p><p>These settings control warnings and tools; they do not automatically rewrite subtitle text.</p><h2 id="confirm-the-import" tabindex="-1">Confirm the import <a class="header-anchor" href="#confirm-the-import" aria-label="Permalink to &quot;Confirm the import&quot;">​</a></h2><p>Before clicking <strong>Confirm</strong>, verify import counts, source/translation roles, episode assignments, video coverage, and project parameters.</p><p><img src="'+l+'" alt="Project import cards showing original, translation, and video resources"></p><p>After confirmation, save the project and inspect several rows from each episode.</p><h2 id="add-or-replace-project-resources" tabindex="-1">Add or replace project resources <a class="header-anchor" href="#add-or-replace-project-resources" aria-label="Permalink to &quot;Add or replace project resources&quot;">​</a></h2><p>Open <strong>Project Setup</strong> again to import more source subtitles, translated subtitles, or videos. When re-importing subtitles, GridSubStudio asks you to choose <strong>Precise Update</strong> or <strong>Whole Replacement</strong>, with a short explanation of each mode in the dialog. Video re-import has no mode choice: after you select files, GridSubStudio updates videos for the corresponding episodes and keeps videos for all other episodes.</p><ul><li><p>Subtitle <strong>Precise Update</strong> is intended for adding episodes or revising selected episodes. “Matching” uses the final episode assignments in <strong>Subtitle Filename Mapping</strong>; it is not a simple filename comparison.</p><ul><li>Existing episodes included in the import are updated, while episodes not included in the import remain unchanged.</li><li>If the import contains an episode that is not yet in the project, that episode is added; an old episode does not have to exist first.</li><li>When updating source subtitles, the imported source text and row structure become authoritative for those episodes. Existing translations are retained where timing and text can be aligned.</li><li>When updating translated subtitles, the imported translation becomes authoritative for those episodes. Existing source text is retained where timing can be aligned.</li></ul></li><li><p>Subtitle <strong>Whole Replacement</strong> means replacing each matched episode as a whole. It uses the same scope as <strong>Precise Update</strong>: both follow the confirmed episode mappings and leave all episodes not matched by this import unchanged.</p><ul><li>For every matched episode, GridSubStudio removes all old rows and registered subtitle sources for that episode, then rebuilds it from the new file. It does not align old and new rows or preserve orphan rows or content from the other subtitle track in that episode.</li><li>For example, if only new Episode 2 source subtitles are imported with <strong>Whole Replacement</strong>, the old source text, translations, and edits in Episode 2 are replaced, while Episodes 1 and 3 remain unchanged.</li><li>An episode not already in the project is added when the new file is mapped to it.</li></ul></li><li><p>Video re-import follows the confirmed <strong>Video Filename Mapping</strong>. A new video replaces the old video for the same episode, a newly mapped episode is added, and videos for episodes not matched by this import remain unchanged.</p></li></ul><p>These operations do not delete the original subtitle or video files on disk. Subtitle <strong>Whole Replacement</strong> clears the existing undo and redo history, so save the project and keep a recoverable copy first.</p><p>Subtitle <strong>Precise Update</strong> does not overwrite rows by row number. GridSubStudio checks exact matches, timing tolerance, splits, merges, and orphan rows within the imported episodes, and opens an alignment review when necessary. After confirming the review, return to Project Setup, verify the mappings, and click <strong>Confirm</strong> to apply the import batch. See <a href="./07-saving-and-exporting.html#re-import-subtitles">Saving and Exporting</a> for the full review workflow. A pending subtitle batch cannot mix <strong>Precise Update</strong> and <strong>Whole Replacement</strong>; finish or cancel the current batch before changing modes.</p><p>After re-importing subtitles or videos, the mapping workbench continues to list existing files not affected by the import alongside newly added or replaced files. Review the complete episode coverage before confirming. Editing a pending subtitle updates the current import plan, while editing an existing subtitle or video updates that saved project resource.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>Confirm is disabled:</strong> wait for imports to finish and resolve missing episodes, conflicts, missing resources, or import errors.</li><li><strong>The wrong episode was detected:</strong> edit the episode in the mapping workbench.</li><li><strong>A video is missing:</strong> re-import it and correct the video mapping.</li><li><strong>ASS export later has no styles:</strong> import an ASS/SSA source template or select a valid style source during export.</li></ul>',41)])])}const w=t(d,[["render",p]]);export{b as __pageData,w as default};
